globalThis.PARTYKIT_DASHBOARD_BASE = "dashboard.partykit.io";

import fs from "fs";
import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { deploy } from "../cli";
import { mockFetchResult, clearMocks } from "./fetchResult-mock";
import { mockConsoleMethods } from "./mock-console";
import type { StaticAssetsManifestType } from "../server";

const std = mockConsoleMethods();

vi.mock("../fetchResult", async () => {
  const { fetchResult } = await import("./fetchResult-mock");
  return {
    fetchResult,
  };
});

const fixture = `${__dirname}/fixture.js`;

process.env.GITHUB_LOGIN = "test-user";
process.env.GITHUB_TOKEN = "test-token";

const currDir = process.cwd();

beforeEach(() => {
  clearMocks();
  // create a tmp dir
  const dirPath = fs.mkdtempSync("pk-test-env");
  // set the cwd to the tmp dir
  process.chdir(dirPath);
});

afterEach(() => {
  // switch back to the original dir
  const tmpDir = process.cwd();
  process.chdir(currDir);
  // remove the tmp dir
  fs.rmdirSync(tmpDir, { recursive: true });
});

type DeployResponse = {
  result: {
    is_first_deploy: boolean;
  };
};

describe("deploy", () => {
  it("should error without a valid script", async () => {
    // @ts-expect-error we're purposely not passing a script path
    await expect(deploy({})).rejects.toThrowErrorMatchingInlineSnapshot(
      '"Missing entry point, please specify \\"main\\" in your config, or pass it in via the CLI"'
    );
  });

  it("should error without a name", async () => {
    await expect(
      // @ts-expect-error we're purposely not passing a name
      deploy({ main: fixture })
    ).rejects.toThrowErrorMatchingInlineSnapshot(
      '"Missing project name, please specify \\"name\\" in your config, or pass it in via the CLI with --name <name>"'
    );
  });

  it("should build and submit a script to the server", async () => {
    let checkedResponse = false;
    mockFetchResult<DeployResponse>(
      "POST",
      "/parties/test-user/test-script",
      (url, options) => {
        expect(url).toMatchInlineSnapshot('"/parties/test-user/test-script"');
        expect(options?.user?.access_token).toBe("test-token");
        checkedResponse = true;
        return {
          result: { is_first_deploy: false },
        };
      }
    );
    await deploy({
      main: fixture,
      name: "test-script",
      config: undefined,
      vars: undefined,
      define: undefined,
      preview: undefined,
      withVars: undefined,
      serve: undefined,
      compatibilityDate: undefined,
      compatibilityFlags: undefined,
      minify: undefined,
    });
    expect(checkedResponse).toBe(true);
  });

  it("should send cli vars without others from config", async () => {
    fs.writeFileSync(
      "partykit.json",
      JSON.stringify({
        name: "test-script",
        vars: {
          a: "a1",
          b: "b2",
          c: "c3",
          d: "d4",
        },
      })
    );

    let checkedResponse = false;
    mockFetchResult<DeployResponse>(
      "POST",
      "/parties/test-user/test-script",
      (url, options) => {
        expect(url).toMatchInlineSnapshot('"/parties/test-user/test-script"');
        expect(options?.user?.access_token).toBe("test-token");

        const form = options?.body as FormData;
        expect(form.get("vars")).toMatchInlineSnapshot(
          '"{\\"a\\":\\"b\\",\\"c\\":\\"d\\"}"'
        );
        checkedResponse = true;
        return {
          result: { is_first_deploy: false },
        };
      }
    );
    await deploy({
      main: fixture,
      name: "test-script",
      config: undefined,
      vars: {
        a: "b",
        c: "d",
      },
      define: undefined,
      preview: undefined,
      withVars: undefined,
      serve: undefined,
      compatibilityDate: undefined,
      compatibilityFlags: undefined,
      minify: undefined,
    });
    expect(checkedResponse).toBe(true);
  });

  it("should send cli vars with config when specified", async () => {
    fs.writeFileSync(
      "partykit.json",
      JSON.stringify({
        name: "test-script",
        vars: {
          a: "a1",
          b: "b2",
          c: "c3",
          d: "d4",
        },
      })
    );

    let checkedResponse = false;
    mockFetchResult<DeployResponse>(
      "POST",
      "/parties/test-user/test-script",
      (url, options) => {
        expect(url).toMatchInlineSnapshot('"/parties/test-user/test-script"');
        expect(options?.user?.access_token).toBe("test-token");

        const form = options?.body as FormData;
        expect(form.get("vars")).toMatchInlineSnapshot(
          '"{\\"a\\":\\"b\\",\\"b\\":\\"b2\\",\\"c\\":\\"d\\",\\"d\\":\\"d4\\"}"'
        );
        checkedResponse = true;
        return {
          result: { is_first_deploy: false },
        };
      }
    );
    await deploy({
      main: fixture,
      name: "test-script",
      config: undefined,
      vars: {
        a: "b",
        c: "d",
      },
      define: undefined,
      preview: undefined,
      withVars: true,
      serve: undefined,
      compatibilityDate: undefined,
      compatibilityFlags: undefined,
      minify: undefined,
    });
    expect(checkedResponse).toBe(true);
  });

  it("should error if the server returns an error", async () => {
    mockFetchResult(
      "POST",
      "/parties/test-user/test-script",
      (_url, _options) => {
        throw new Error("Not OK");
      }
    );
    await expect(
      deploy({
        main: fixture,
        name: "test-script",
        config: undefined,
        vars: undefined,
        define: undefined,
        preview: undefined,
        withVars: undefined,
        serve: undefined,
        compatibilityDate: undefined,
        compatibilityFlags: undefined,
        minify: undefined,
      })
    ).rejects.toThrowErrorMatchingInlineSnapshot('"Not OK"');
  });

  it('should warn if using "serve" in the config', async () => {
    let checkedResponse = false;
    mockFetchResult<DeployResponse>(
      "POST",
      "/parties/test-user/test-script",
      (url, options) => {
        expect(url).toMatchInlineSnapshot('"/parties/test-user/test-script"');
        expect(options?.user?.access_token).toBe("test-token");

        checkedResponse = true;
        return {
          result: { is_first_deploy: false },
        };
      }
    );

    mockFetchResult<StaticAssetsManifestType>(
      "GET",
      "/parties/test-user/test-script/assets",
      (url, options) => {
        expect(url).toMatchInlineSnapshot(
          '"/parties/test-user/test-script/assets"'
        );
        expect(options?.headers).toMatchInlineSnapshot(`
          {
            "Content-Type": "application/json",
          }
        `);
        expect(options?.user?.access_token).toBe("test-token");

        return {
          devServer: "",
          browserTTL: undefined,
          edgeTTL: undefined,
          singlePageApp: false,
          assets: {},
        };
      }
    );

    mockFetchResult<null>(
      "POST",
      "/parties/test-user/test-script/assets",
      (url, options) => {
        expect(url).toMatchInlineSnapshot(
          '"/parties/test-user/test-script/assets"'
        );
        expect(options?.headers).toMatchInlineSnapshot(`
          {
            "Content-Type": "application/json",
          }
        `);
        expect(options?.user?.access_token).toBe("test-token");

        expect(options?.body).toMatchInlineSnapshot(
          '"{\\"devServer\\":\\"\\",\\"assets\\":{}}"'
        );
        return null;
      }
    );

    fs.writeFileSync(
      "partykit.json",
      JSON.stringify({
        name: "test-script",
        serve: "./public",
      })
    );

    fs.mkdirSync("public");

    await deploy({
      main: fixture,
      name: "test-script",
      config: undefined,
      vars: undefined,
      define: undefined,
      preview: undefined,
      withVars: undefined,
      serve: undefined,
      compatibilityDate: undefined,
      compatibilityFlags: undefined,
      minify: undefined,
    });

    expect(checkedResponse).toBe(true);

    expect(std).toMatchInlineSnapshot(`
      {
        "debug": "",
        "err": "",
        "info": "",
        "out": "Deployed ./../packages/partykit/src/tests/fixture.js to https://test-script.test-user.partykit.dev",
        "warn": "",
      }
    `);
  });
});

import { describe, expect, it } from "vitest";
import { levelGet, levelPut, getLevelBulkData } from "../storage";
// import { RoomStorage } from "partykit/src/cli";

describe.skip("storage layer", () => {
  it("should be able to set and get", async () => {
    // @ts-expect-error - RoomStorage is not exported
    const storage = new RoomStorage();
    await levelPut(storage, ["v1_sv", "bar"], new Uint8Array([1, 2, 3]));
    const foo = await levelGet(storage, ["v1_sv", "bar"]);
    expect(foo).toEqual(new Uint8Array([1, 2, 3]));
  });

  it("should be able to set and get big values", async () => {
    // @ts-expect-error - RoomStorage is not exported
    const storage = new RoomStorage();
    const value = new Uint8Array(100000);
    await levelPut(storage, ["v1_sv", "bar"], value);
    const foo = await levelGet(storage, ["v1_sv", "bar"]);
    expect(foo).toEqual(value);
  });

  it("should be able to set and get bulk", async () => {
    // @ts-expect-error - RoomStorage is not exported
    const storage = new RoomStorage();
    await levelPut(storage, ["v1_sv", "bar"], new Uint8Array([1, 2, 3]));
    await levelPut(storage, ["v1_sv", "baz"], new Uint8Array([4, 5, 6]));
    const foo = await getLevelBulkData(storage, {
      gte: ["v1_sv", ""],
      lt: ["v1_sv", "zzz"],
      keys: true,
      values: true,
    });
    expect(foo).toEqual([
      {
        key: ["v1_sv", "bar"],
        value: new Uint8Array([1, 2, 3]),
      },
      {
        key: ["v1_sv", "baz"],
        value: new Uint8Array([4, 5, 6]),
      },
    ]);
  });

  it("should be able to set and get big bulk", async () => {
    // @ts-expect-error - RoomStorage is not exported
    const storage = new RoomStorage();
    const value = new Uint8Array(100000);
    await levelPut(storage, ["v1_sv", "bar"], value);
    await levelPut(storage, ["v1_sv", "baz"], value);
    const foo = await getLevelBulkData(storage, {
      gte: ["v1_sv", ""],
      lt: ["v1_sv", "zzz"],
      keys: true,
      values: true,
    });
    expect(foo).toEqual([
      {
        key: ["v1_sv", "bar"],
        value,
      },
      {
        key: ["v1_sv", "baz"],
        value,
      },
    ]);
  });
});

