import open from "open";
import http from "http";
import getPort from "get-port";
import type { Socket } from "net";

declare const PARTYKIT_DASHBOARD_BASE: string | undefined;

const DASHBOARD_BASE =
  process.env.PARTYKIT_DASHBOARD_BASE || PARTYKIT_DASHBOARD_BASE;

if (!DASHBOARD_BASE) {
  throw new Error("PARTYKIT_DASHBOARD_BASE not defined");
}

export async function signInWithBrowser(): Promise<
  | {
      token: string;
      teamId: string;
    }
  | { aborted: true }
> {
  const port = await getPort({ port: [1998, 1997, 1996] });

  let sockets: Socket[] = [];

  return new Promise((resolve, reject) => {
    // create a minimal web server to handle the callback from the browser
    const server = http
      .createServer((req, res) => {
        if (!req.url?.startsWith("/device/callback?")) {
          return;
        }

        res.setHeader("Access-Control-Allow-Origin", "*");
        res.setHeader("Access-Control-Allow-Headers", "Authorization");

        if (req.method === "OPTIONS") {
          res.statusCode = 204;
          res.end();
        }

        if (req.method === "POST") {
          try {
            // "host" is arbitrary here, added just so we can parse the url
            const url = new URL(`http://host${req.url}`);

            const error = url.searchParams.get("error");
            if (error) {
              res.statusCode = 200;
              res.end("OK");
              resolve({ aborted: true });
            } else {
              const token = url.searchParams.get("token");
              const teamId = url.searchParams.get("teamId");
              if (token && teamId) {
                res.statusCode = 200;
                res.end("OK");
                resolve({ token, teamId });
              } else {
                res.statusCode = 400;
                res.end("Invalid parameters");
                reject(new Error("Invalid parameters"));
              }
            }
          } catch (e) {
            reject(e);
          } finally {
            // ensure all connections are closed to allow process to exit cleanly
            server.close();
            server.unref();
            sockets.forEach((s) => s.destroy());
            sockets = [];
          }
        }
      })
      .listen(port);

    server.on("connection", function (socket) {
      // track live connections
      sockets.push(socket);
      socket.on("close", () => {
        sockets = sockets.filter((s) => s !== socket);
        socket.destroy();
      });
    });

    // the local server url the login flow will redirect back to
    const redirectUrl = `http://localhost:${port}/device/callback`;

    // the remote server url that will handle the login flow
    const loginUrl = `${DASHBOARD_BASE}/login/device?redirectUrl=${encodeURIComponent(
      redirectUrl
    )}`;

    open(loginUrl).catch(() => {
      console.error(
        `Failed to open a browser, please visit the following page to complete the login process: ${loginUrl}`
      );
    });
  });
}

import chalk from "chalk";
import { fetch } from "undici";
import open from "open";
import { version as packageVersion } from "../../package.json";

import * as ConfigSchema from "../config-schema";
import { userConfigSchema, type UserConfig } from "../config";
import countdown from "../countdown";

export const configSchema = ConfigSchema.schema;
export type Config = ConfigSchema.Config;

const GITHUB_APP_ID = "670a9f76d6be706f5209";

export async function signInWithGitHub(): Promise<UserConfig> {
  // run github's oauth device flow
  // https://docs.github.com/en/developers/apps/building-oauth-apps/authorizing-oauth-apps#device-flow
  const res = await fetch("https://github.com/login/device/code", {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      "User-Agent": `partykit/${packageVersion}`,
      "X-PartyKit-Version": packageVersion,
    },
    body: JSON.stringify({
      client_id: GITHUB_APP_ID,
    }),
  });

  if (!res.ok) {
    throw new Error(
      `Failed to get device code: ${res.status} ${res.statusText}`
    );
  }

  const { device_code, user_code, verification_uri, expires_in, interval } =
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (await res.json()) as any;

  console.log(
    `We will now open your browser to ${chalk.bold(
      verification_uri
    )}\nPlease paste the code ${chalk.bold(
      user_code
    )} (copied to your clipboard) and authorize the app.`
  );

  await countdown("Opening browser", 5);

  console.log(`Waiting for you to authorize...`);

  // we do this because for some reason the clipboardy package doesn't work
  // with a direct import up top
  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
  // @ts-ignore kill me, bring me sweet release of death please
  const { default: clipboardy } = await import("clipboardy");
  clipboardy.writeSync(user_code);

  open(verification_uri).catch(() => {
    console.error(
      `Failed to open ${verification_uri}, please copy the code ${user_code} to your clipboard`
    );
  });

  const start = Date.now();
  while (Date.now() - start < expires_in * 1000) {
    const res = await fetch("https://github.com/login/oauth/access_token", {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        "User-Agent": `partykit/${packageVersion}`,
        "X-PartyKit-Version": packageVersion,
      },
      body: JSON.stringify({
        client_id: GITHUB_APP_ID,
        device_code,
        grant_type: "urn:ietf:params:oauth:grant-type:device_code",
      }),
    });

    if (!res.ok) {
      throw new Error(
        `Failed to get access token: ${res.status} ${res.statusText}`
      );
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { access_token, error } = (await res.json()) as any;

    // now get the username
    const githubUserDetails = (await (
      await fetch("https://api.github.com/user", {
        headers: {
          Authorization: `Bearer ${access_token}`,
          "User-Agent": `partykit/${packageVersion}`,
          "X-PartyKit-Version": packageVersion,
        },
      })
    ).json()) as { login: string };

    if (access_token) {
      return userConfigSchema.parse({
        access_token,
        login: githubUserDetails.login,
        type: "github",
      });
    }

    if (error === "authorization_pending") {
      // try again in a bit
      await new Promise((resolve) => setTimeout(resolve, interval * 1000));
      continue;
    }

    throw new Error(`Unexpected error: ${error}`);
  }

  throw new Error("Login failed.");
}

import type Clerk from "@clerk/clerk-js";
import clerk from "@clerk/clerk-js/headless/index.js";

const ClerkConstructor = clerk.default;

global.window = global.window || {};

type TokenStore = {
  token?: string;
};

const CLERK_PUBLISHABLE_KEY = "pk_live_Y2xlcmsucGFydHlraXQuaW8k";

const clerkFactory = ({ publishableKey }: { publishableKey: string }) => {
  /**
   * The Clerk CLI is meant for browser use, and relies on cookies by default.
   * Here we make it work by passing the token in the Authorization header instead.
   */
  return async ({ tokenStore }: { tokenStore: TokenStore }): Promise<Clerk> => {
    const clerk: Clerk = new ClerkConstructor(publishableKey);
    // pass captured or provided token in subsequent requests
    clerk.__unstable__onBeforeRequest(async (requestInit) => {
      requestInit.credentials = "omit";
      requestInit.url?.searchParams.append("_is_native", "1");
      (requestInit.headers as Headers).set(
        "authorization",
        tokenStore.token || ""
      );
    });

    // capture token from responses for future use
    clerk.__unstable__onAfterResponse(async (_, response) => {
      const authHeader = response?.headers.get("authorization");
      if (authHeader) {
        tokenStore.token = authHeader;
      }
    });

    await clerk.load({ standardBrowser: false });

    return clerk;
  };
};

export const createClerkClient = clerkFactory({
  publishableKey: CLERK_PUBLISHABLE_KEY,
});

export const fetchClerkClientToken = async (signInToken: string) => {
  // the login process will populate the token in this object
  const tokenStore = {
    token: undefined,
  };

  const clerk = await createClerkClient({ tokenStore });
  const res = await clerk.client?.signIn.create({
    strategy: "ticket",
    ticket: signInToken,
  });

  if (res && res.status !== "complete") {
    throw new Error(`Flow did not complete: ${JSON.stringify(res)}`);
  }

  if (!tokenStore.token) {
    throw new Error("No client token received");
  }

  // `clerk.session` won't be populated on device, but session should exist
  const session = clerk.client?.activeSessions?.[0];
  if (!session || !session.user) {
    throw new Error("No session created");
  }

  return {
    access_token: tokenStore.token,
    username: session.user.username,
  };
};
